/**
 * Like uniform(), but in production emits a const node to reduce uniform bandwidth.
 * In development, it keeps a live uniform with a readable name for GUI tweaking.
 *
 * @param {*} value
 * @param {Object} options
 * @param {string} options.name - Uniform name for debugging.
 * @param {'float'|'vec2'|'vec3'|'vec4'|'color'} options.type - TSL type name.
 * @returns {*}
 */
export function uniformPlus(value: any, { name, type }: {
    name: string;
    type: "float" | "vec2" | "vec3" | "vec4" | "color";
}): any;
